#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string input;
    getline(cin, input);
    istringstream iss(input);
    int baseW, numberM;
    iss >> baseW >> numberM;

    int tempNumber = numberM;
    int maxExponent = (int)(log(tempNumber) / log(baseW));
    int arraySize = maxExponent + 2;
    vector<int> digitArray(arraySize, 0);

    for (int power = maxExponent; power >= 0; --power) {
        digitArray[power] = (int)((tempNumber / pow(baseW, power)) % baseW);
    }

    bool isSequenceValid = true;
    for (int i = 0; i <= maxExponent; ++i) {
        if (digitArray[i] >= baseW) {
            digitArray[i] %= baseW;
            if (i + 1 < arraySize) {
                digitArray[i + 1]++;
            }
        }
        if (digitArray[i] != 0 && digitArray[i] != 1) {
            digitArray[i]++;
        }
        if (digitArray[i] >= baseW) {
            digitArray[i] %= baseW;
            if (i + 1 < arraySize) {
                digitArray[i + 1]++;
            }
        }
    }

    for (int i = 0; i < arraySize; ++i) {
        if (digitArray[i] != 0 && digitArray[i] != 1) {
            isSequenceValid = false;
            break;
        }
    }
    cout << (isSequenceValid ? "YES" : "NO") << "\n";
    return 0;
}
